#!/usr/bin/env bash
set -euo pipefail
echo "Aplicando Token Monitor Beta 0.2.2 — carteira e backup..."

mkdir -p "$(dirname "app/src/main/java/com/jean/tokenmonitor/MainActivity.java")"
echo "" | base64 -d > "app/src/main/java/com/jean/tokenmonitor/MainActivity.java"

mkdir -p "$(dirname "app/src/main/java/com/jean/tokenmonitor/WalletManager.java")"
echo "" | base64 -d > "app/src/main/java/com/jean/tokenmonitor/WalletManager.java"

mkdir -p "$(dirname "app/src/main/java/com/jean/tokenmonitor/BackupCrypto.java")"
echo "" | base64 -d > "app/src/main/java/com/jean/tokenmonitor/BackupCrypto.java"

mkdir -p "$(dirname "app/build.gradle")"
echo "" | base64 -d > "app/build.gradle"

mkdir -p "$(dirname ".github/workflows/build-apk.yml")"
echo "" | base64 -d > ".github/workflows/build-apk.yml"

mkdir -p "$(dirname "README.md")"
echo "" | base64 -d > "README.md"

git config user.name "Token Monitor Setup"
git config user.email "tokenmonitor@users.noreply.github.com"
git add app .github README.md
git commit -m "Adicionar carteira local e backup criptografado" || true
git push origin HEAD
echo "Concluído. Aguarde o GitHub Actions gerar TokenMonitorJean-Beta-0.2.2-Wallet."
